package com.novara.banking.notification;import com.novara.banking.identity.CurrentIdentity;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController{private final NotificationService service;private final CurrentIdentity identities;public NotificationController(NotificationService s,CurrentIdentity i){service=s;identities=i;}@GetMapping List<NotificationService.View> list(Authentication a,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){return service.list(identities.from(a),Math.max(0,page),Math.min(100,Math.max(1,size)));}@GetMapping("/unread-count") Map<String,Long> unread(Authentication a){return Map.of("count",service.unread(identities.from(a)));}@PostMapping("/{id}/read") void read(Authentication a,@PathVariable UUID id){service.read(identities.from(a),id);}@PostMapping("/read-all") void readAll(Authentication a){service.readAll(identities.from(a));}@GetMapping("/preferences") NotificationService.Preferences preferences(Authentication a){return service.preferences(identities.from(a));}@PutMapping("/preferences") NotificationService.Preferences preferences(Authentication a,@Valid @RequestBody NotificationService.Preferences p){return service.preferences(identities.from(a),p);}}
